from pathlib import Path
import json
p=Path('knowledge/documentation-pack.json');d=json.loads(p.read_text(encoding='utf-8'))
d['articles']=[a for a in d['articles'] if not a['slug'].startswith('nigeria-guide-')]
rows=[
('platform','End-to-end service journey','Follow the NigeriaG2P service journey','Know which application handles each part of the demonstration.','Start with the persona workspace or All services.\nRegister the household and submit it for independent review.\nAfter approval, track the programme application, eligibility and enrolment through the relevant service.\nUse reporting to inspect recorded outcomes.','An existing account with the required task permissions.','Open help at the stage you are working on.','Household approval does not itself grant a benefit or prove a payment. Demonstration records are fictional.','/registration/workspace'),
('platform','Persona and permission','Understand personas and account permissions','Personas organise the experience around citizen, registration, verification and supervision tasks.','Choose the persona relevant to the client walkthrough.\nRead the task list and current status.\nSign in with an authorised account to perform available actions.','Existing account permission for any operational action.','Use the linked service for your assigned task.','The persona selector and demo walkthrough cannot grant new permissions.','/?persona=all'),
('intake','Registration readiness','Prepare a household registration','Collect the information required by the household form before submission.','Check required household details and location fields.\nCheck member details and relationships.\nSave and review the draft.\nResolve form errors, then submit once for review.','Fictional household information for this sandbox.','Retain the reference and track the submitted status.','Submission is different from approval. Avoid creating another household merely because review is pending.','/registration/'),
('intake','Returned registration corrections','Respond to a returned registration','Use reviewer feedback to correct the original household submission.','Open the returned record.\nRead the reason for correction.\nUpdate the relevant fields and check the household members and location.\nResubmit through the form when the application allows it.','Access to the returned household and its feedback.','Track the new review status.','Correct the original record instead of making a duplicate application.','/registration/workspace'),
('review','Verification readiness','Prepare an independent registration review','A verifier checks the submitted information and recorded evidence before deciding.','Open a pending record assigned or available to your account.\nCompare household details, members and geographic information.\nRead recorded evidence and provenance.\nUse the available decision controls with a useful reason for any return.','Verification permission and access to the submitted record.','Check the resulting status and activity record.','A map dot or AI answer is not identity or residence verification.','/registration/staff'),
('review','Registration audit reference','Investigate a registration status question','Use the record reference and activity rather than relying on recollection.','Find the household or submission reference.\nInspect the current review status and recorded activity.\nCompare feedback and the relevant timestamp.\nEscalate discrepancies to the responsible staff member.','Permission to inspect the record.','Follow the appropriate correction or review process.','Screens may show different stages of processing. Do not approve a case just to resolve a display inconsistency.','/registration/workspace'),
('beneficiary','Application preparation','Prepare a programme application','A programme application is a separate step after the required registration process.','Check that the household registration has the required status.\nOpen the programme application route available to your account.\nReview the programme and required form information.\nSubmit and retain the application reference.','An eligible application route and the information required by the programme.','Track the application and its eligibility/enrolment status.','The library does not define government eligibility rules. Use only the programme criteria configured and approved by its owner.','/registration/workspace'),
('beneficiary','Status meaning','Interpret household and programme statuses','Understand what the application has actually recorded at each stage.','Read the household review status first.\nCheck the programme application separately.\nDistinguish pending review, returned details, approved registration, eligibility and enrolment.\nUse the current screen’s next-step guidance.','Access to your household or assigned record.','Ask the responsible officer about a blocked stage.','Approved registration and enrolled status are not confirmation of a real payment in this sandbox.','/registration/workspace'),
('geography','Map intensity and counting','Interpret state colours on the Nigeria map','State shading summarises the records included by the current map filters.','Check the selected filters and counting unit.\nRead the colour legend before comparing states.\nInspect the displayed state count.\nUse household points to examine coordinate coverage rather than infer approval or need.','Geography page access.','Compare the map with the filtered record list and coverage summary.','A darker state indicates more included records, not a higher poverty rate or a verified population estimate.','/registration/geography'),
('geography','Coordinate quality','Check household coordinate quality','Coordinate provenance determines whether a household point is useful beyond a demonstration.','Check latitude, longitude and coordinate source.\nDistinguish synthetic demo points from captured or verified residence points.\nKeep the recorded state and LGA structure intact.\nFlag missing or inconsistent locations for authorised correction.','Permission to view geographic records.','Review the coverage and coordinate provenance summary.','Demo points are not verified households or LGA positions. Do not infer a new LGA from a synthetic coordinate.','/registration/geography'),
('staff-portal','Staff service navigation','Choose the correct staff service','Use the staff portal and shared navigation to reach the task-specific application.','Sign in through the existing staff route.\nChoose the service for your task.\nConfirm the application and record context before acting.\nOpen stage help when the next step is unclear.','An existing staff account and assigned permissions.','Continue the task in the target service.','Access to one service does not imply permission for every other service.','/'),
('staff-portal','Access troubleshooting','Resolve a staff access problem','Separate an expired session from a missing task permission.','Confirm the correct service and staff sign-in route.\nSign in again if the session has expired.\nCheck whether the task is assigned and the required role is present.\nReport the service, screen and error to the access administrator without sharing credentials.','Your existing account and a non-sensitive problem description.','Retry after the authorised correction.','Never put passwords, session cookies or tokens into knowledge articles or AI questions.','/registration/workspace'),
('knowledge','Source-aware guidance','Use source-linked task guidance','Library articles explain local tasks or summarise official upstream reference material.','Check the article’s service and workflow stage.\nRead its local-workflow or upstream-reference label.\nUse the source link for further detail.\nConfirm release-dependent features with the application administrator.','Published library access.','Follow the actual controls available to your account.','An upstream feature description is not proof that the feature is enabled in NigeriaG2P.','/registration/knowledge'),
('knowledge','Knowledge content maintenance','Maintain a guidance article','Staff can update guidance through the existing versioned review process.','Open Manage guidance with an authorised account.\nCreate or edit the service, stage, audience and six guidance fields.\nSave the draft and submit for independent review.\nAn authorised reviewer checks it before supervisor publication.','Existing knowledge editing/review/publication permissions.','Verify the published version in the library and screen help.','Drafts remain separate from published content. Authors cannot review their own drafts.','/registration/knowledge/admin'),
('knowledge','AI source verification','Check a local AI answer','The local assistant retrieves published guidance and presents relevant source links.','Select the service, role and workflow stage.\nAsk a task question without personal information.\nRead the linked source articles and any version caveats.\nUse the application’s authorised controls for the actual task.','An existing account and an available local model.','Consult an authorised staff member if guidance is insufficient.','AI may be wrong and cannot verify identities, approve cases, set policy or initiate payments.','/registration/ai'),
('knowledge','AI drafting review','Review AI-suggested guidance before saving','A generated suggestion is editable form text, not a published rule.','Choose the service, audience and stage.\nGenerate and read the suggestion preview.\nApply it only after checking the contents.\nConfirm missing facts, then save and follow independent review.','Existing knowledge editing permission.','Submit the corrected draft for review.','Applying replaces the six guidance fields but does not save or publish; never invent eligibility thresholds.','/registration/knowledge/admin/new'),
]
for i,(module,stage,title,purpose,steps,requirements,next_step,issues,url)in enumerate(rows):
 d['articles'].append(dict(slug='nigeria-guide-'+module+'-'+str(i+1),module=module,stage=stage,audience='all',title=title,purpose=purpose,steps=steps,requirements=requirements,next_step=next_step,issues=issues,sources=[dict(title='NigeriaG2P local application workflow',url='https://nigeriag2p.com'+url)],scope='local_workflow',sources_checked_on='2026-10-05',origin='system:documentation-import'))
p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8');print('Total new task guides:',len(d['articles']))
seed=Path('knowledge-seed.json');s=json.loads(seed.read_text(encoding='utf-8'));old={a['slug']for a in s['articles']};s['articles'] += [a for a in d['articles'] if a['slug']not in old];seed.write_text(json.dumps(s,ensure_ascii=False,indent=2),encoding='utf-8');print('Seed total:',len(s['articles']))
